public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    int count = 0;

    while (count < len) {
        int b = str.charAt(index++);
        if ((b & 128) == 0) { // 7-bit character
            size++;
        } else if ((b & 192) == 192) { // 11-bit character
            size += 2;
        } else if ((b & 128) == 128 && (b & 64) == 64) { // 16-bit character
            size += 3;
        } else if ((b & 128) == 128 && (b & 128) == 128) { // 21-bit character
            size += 4;
        } else {
            return Integer.MAX_VALUE; // Invalid UTF-8 sequence
        }

        count++;
    }

    return size;
}
