public static String unescapeJava(String str) {
    StringBuilder newStr = new StringBuilder();
    int len = str.length();
    String hex = null;

    for (int i = 0; i < len; i++) {
        char currentChar = str.charAt(i);

        // Handle escaped characters
        if (currentChar == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == '\'') {
                    newStr.append(nextChar);
                    i++;
                } else if (nextChar == 'n') {
                    newStr.append('\n');
                    i++;
                } else if (nextChar == 't') {
                    newStr.append('\t');
                    i++;
                } else if (nextChar >= '0' && nextChar <= '9') {
                    hex = nextChar + str.charAt(i + 1);
                    int value = Integer.parseInt(hex, 16);
                    newStr.append((char) value);
                    i += 2;
                } else {
                    // Invalid escape sequence
                    throw new Exception("Invalid escape sequence: \\u" + hex);
                }
            } else {
                // Invalid escape sequence with no next character
                throw new Exception("Invalid escape sequence: \\uf");
            }
        } else {
            newStr.append(currentChar);
        }
    }

    return newStr.toString();
}
