    // Split the path into parent directories
    String[] pathComponents = path.split("/");
    // Split the relative path into parts
    String[] relativePathComponents = relativePath.split("/");

    // Process each part of the relative path
    for (int i = 0; i < relativePathComponents.length; i++) {
        // Check if the relative path is a directory
        if (relativePathComponents[i].equals(".")) {
            continue;
        } else if (relativePathComponents[i].equals("..")) {
            // Check if there is a parent directory to move to
            if (pathsComponents.length > 1) {
                pathsComponents = Arrays.copyOfRange(pathsComponents, 0, pathsComponents.length - 1);
            } else {
                // If there is no parent directory, return the original path
                return path;
            }
        } else {
            // Add the relative path part to the path
            pathsComponents.add(relativePathComponents[i]);
        }
    }

    // Join the path components with a /
